// Full 5e SRD reference lookups (2014 rules) — every spell, class feature,
// racial trait, class progression table, condition, magic item, and piece of
// gear. Data files in ./srd/ are generated by `node tools/build-srd.mjs` from
// the 5e-bits/5e-database JSON (CC-BY-4.0).
//
// The hand-curated maps in gameData.js still take priority for abilities
// (compact, table-tuned) and act as the safety net for non-SRD content the
// party uses (Hex, Toll the Dead, changeling traits, homebrew…).
import spells from './srd/spells.json'
import features from './srd/features.json'
import traits from './srd/traits.json'
import classes from './srd/classes.json'
import srdConditions from './srd/conditions.json'
import magicItems from './srd/magic-items.json'
import gear from './srd/gear.json'
import { SPELL_DESCRIPTIONS, ABILITY_DESCRIPTIONS } from './gameData'

const NO_DESC = 'No description available.'

// same normalization as the build script
const norm = (s) => String(s || '').toLowerCase().replace(/[’'".,()\-–—]/g, ' ').replace(/\s+/g, ' ').trim()

// Try progressively looser forms of the name: exact → parenthetical stripped
// ("Sneak Attack (2d6)") → trailing dice/counts stripped ("Sneak Attack 2d6",
// "Arrows ×15") → naive singular ("Arrows" → "Arrow").
function candidates(name) {
  const out = []
  const push = (v) => { const n = norm(v); if (n && !out.includes(n)) out.push(n) }
  push(name)
  push(String(name).replace(/\s*\(.*?\)\s*/g, ' '))
  push(norm(name).replace(/\s+(?:\d*d\d+|×?\s*\d+|x\s*\d+)\s*$/i, ''))
  const last = out[out.length - 1]
  if (last && last.endsWith('s')) push(last.slice(0, -1))
  return out
}
function find(table, name) {
  for (const key of candidates(name)) if (table[key]) return table[key]
  return null
}

// normalized indexes of the curated gameData maps, so lookups tolerate
// naming drift ("Sneak Attack (2d6)" vs "Sneak Attack 2d6")
const buildIndex = (map) => {
  const idx = {}
  for (const [k, v] of Object.entries(map)) idx[norm(k)] = v
  return idx
}
const curatedSpells = buildIndex(SPELL_DESCRIPTIONS)
const curatedAbilities = buildIndex(ABILITY_DESCRIPTIONS)

// ---------- spells ----------
export const srdSpell = (name) => find(spells, name)

const ordinal = (n) => `${n}${['th', 'st', 'nd', 'rd'][n % 10 > 3 || (n % 100 >= 11 && n % 100 <= 13) ? 0 : n % 10]}`

// Full plain-text spell card (render with white-space: pre-wrap)
export function spellCardText(s) {
  const head = [
    s.lvl === 0 ? `Cantrip · ${s.school}` : `${ordinal(s.lvl)} level · ${s.school}${s.ritual ? ' · Ritual' : ''}`,
    [s.time, s.range, s.comp].filter(Boolean).join(' · '),
    `Duration: ${s.conc ? 'Concentration, ' : ''}${s.dur}`,
    s.classes.length ? s.classes.join(', ') : '',
  ].filter(Boolean).join('\n')
  const body = [s.desc, s.higher ? `At Higher Levels: ${s.higher}` : ''].filter(Boolean).join('\n\n')
  return `${head}\n\n${body}`
}

// Best available spell description: full SRD card → curated one-liner → fallback
export function describeSpell(name, fallback) {
  const s = srdSpell(name)
  if (s) return spellCardText(s)
  return find(curatedSpells, name) || fallback || NO_DESC
}

// ---------- abilities: class features, racial traits, feats ----------
// Curated first (compact + covers non-SRD), then SRD feature/trait full text.
export function describeAbility(name, fallback, klass) {
  const curated = find(curatedAbilities, name)
  if (curated) return curated
  const entries = find(features, name)
  if (entries) {
    const e = (klass && entries.find((x) => x.cls === klass || x.sub === klass)) || entries[0]
    const src = [e.sub || e.cls, e.lvl ? `level ${e.lvl}` : ''].filter(Boolean).join(' · ')
    return (src ? `${src}\n\n` : '') + e.desc
  }
  const t = find(traits, name)
  if (t) return t.desc
  return fallback || NO_DESC
}

// ---------- items: magic items first, then mundane gear ----------
export function describeItem(name, fallback) {
  const m = find(magicItems, name)
  if (m) return `${[m.category, m.rarity].filter(Boolean).join(' · ')}\n\n${m.desc}`
  const g = find(gear, name)
  if (g) {
    const meta = [
      g.category,
      g.dmg ? `Damage: ${g.dmg}${g.dmg2h ? ` (${g.dmg2h} two-handed)` : ''}` : '',
      g.range ? `Range: ${g.range}` : '',
      g.ac ? `AC: ${g.ac}` : '',
      g.strMin ? `Str ${g.strMin} required` : '',
      g.stealthDis ? 'Stealth disadvantage' : '',
      g.props?.length ? g.props.join(', ') : '',
    ].filter(Boolean).join(' · ')
    return [meta, g.desc].filter(Boolean).join('\n\n') || fallback || NO_DESC
  }
  return fallback || NO_DESC
}

// ---------- conditions (full SRD text) ----------
export const conditionText = (name) => find(srdConditions, name)?.desc || null

// ---------- class progression ----------
// classes.json: { [index]: { name, hitDie, saves, spellAbility,
//   levels: { n: { prof, features[], cantrips?, known?, slots?[9], counters? } },
//   subclasses: { Name: { flavor, desc, levels } } } }
export const classInfo = (klass) => classes[norm(klass).replace(/\s+/g, '-')] || null

// spell slots [lvl1..lvl9] for a class at a character level (null = non-caster)
export function spellSlotsFor(klass, level) {
  const c = classInfo(klass)
  return c?.levels?.[level]?.slots || null
}

// every feature name a class (and optional subclass) has gained by `level`
export function featuresByLevel(klass, level, subclass) {
  const c = classInfo(klass)
  if (!c) return []
  const out = []
  for (let n = 1; n <= level; n++) {
    for (const f of c.levels?.[n]?.features || []) out.push({ name: f, lvl: n })
    const sub = subclass && c.subclasses?.[subclass]
    for (const f of sub?.levels?.[n]?.features || []) out.push({ name: f, lvl: n, sub: subclass })
  }
  return out
}

export const SRD = { spells, features, traits, classes, conditions: srdConditions, magicItems, gear }
